------------------------------
---- WAYBAR AUTO-HIDE ----
------------------------------

-- Waybar only runs on the main monitor (DP-2, dp2.jsonc). Hide it whenever
-- that monitor is showing a fullscreen window, show it again otherwise.
local hidden = false
local function syncWaybarVisibility()
    local m = hl.get_monitor("DP-2")
    local ws = m and m.active_workspace
    local shouldHide = (ws ~= nil) and ws.has_fullscreen or false

    if shouldHide ~= hidden then
        hidden = shouldHide
        hl.exec_cmd("pkill -SIGUSR1 -f '[w]aybar -c .*dp2.jsonc'")
    end
end

hl.on("window.fullscreen", syncWaybarVisibility)
hl.on("workspace.active", syncWaybarVisibility)
hl.on("window.close", syncWaybarVisibility)

-- Refresh the waybar custom/wsN workspace buttons (active-state highlight,
-- show/hide empty workspaces) whenever workspace occupancy or focus changes.
local function refreshWaybarWorkspaces()
    hl.exec_cmd("pkill -RTMIN+8 waybar")
end
hl.on("workspace.active", refreshWaybarWorkspaces)
hl.on("workspace.created", refreshWaybarWorkspaces)
hl.on("workspace.removed", refreshWaybarWorkspaces)
hl.on("window.open", refreshWaybarWorkspaces)
hl.on("window.close", refreshWaybarWorkspaces)
hl.on("window.move_to_workspace", refreshWaybarWorkspaces)


