hl.layer_rule({
    name  = "waybar-blur",
    match = { namespace = "^waybar$" },
    blur  = true,
    ignore_alpha = 0.5,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- gsimplecal popup: centred under the Waybar clock, which spans x 2266..2407 on DP-2
-- (centre 2336). Window is 328px wide with the gsimplecal-dark theme, so x = 2336-164.
-- Re-check this if the theme's font size changes: the window width changes with it.
hl.window_rule({
    name  = "position-gsimplecal",
    match = { class = "gsimplecal" },

    move  = "monitor_w-388 50",
    float = true,
})
